package com.skyclone.mod.enchanting;

import com.google.gson.annotations.SerializedName;
import com.skyclone.api.item.EnchantDef;
import com.skyclone.api.item.ItemCategory;
import com.skyclone.api.item.ItemDef;
import com.skyclone.api.item.Rarity;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;

/**
 * One enchantment as generated by {@code tools/gen/enchanting/gen_enchanting.py} into
 * {@code data/enchanting/enchants.json}. Pure data + pure helpers (no Bukkit), so the unit tests
 * can load the shipping file and check it.
 *
 * <p>{@code values[series][level-1]}: series 0 is the headline number (the one core prints in item
 * lore), further series are the secondary numbers some enchants have (Giant Killer's cap, Cleave's
 * radius...). Levels below {@link #minLevel} are padded with 0.
 */
public final class EnchantSpec {

    public String id;
    public String name;
    /** The reference game's name, kept only for docs/names; never shown to players. */
    public String referenceName;
    /** Other ids this enchant answers to: its names snake-cased ("woodsplitter", "bank"), which is how
     *  the skills table names its unlocks. Resolved by {@link EnchantRegistry#spec}; registered with core. */
    public List<String> aliases = new ArrayList<>();
    public boolean ultimate;
    public int minLevel = 1;
    public int maxLevel = 1;
    /** Highest level the enchanting table offers; 0 = not on the table at all. */
    public int tableMax;
    /** False for "cannot be combined" enchants (level-by-use ones, Delicate...). */
    public boolean combinable = true;
    /** ItemCategory names this enchant applies to. */
    public List<String> categories = new ArrayList<>();
    /** Item tags that also allow it ("farming_tool" for farming tools that are not hoes). */
    public List<String> tags = new ArrayList<>();
    /** Specific item ids it applies to regardless of category (Ultimate Jest). */
    public List<String> itemIds = new ArrayList<>();
    public List<String> conflicts = new ArrayList<>();
    public double[][] values = new double[0][];
    public List<String> rarity = new ArrayList<>();
    /** Enchanting-table XP-level cost per level (index 0 = level I). May be shorter than maxLevel. */
    public int[] cost = new int[0];
    /** Enchanting skill level needed to use / apply it (research 02, Enchanting road). 0 = none. */
    public int skill;
    /** Full description template; {0} {1} {2} = value series. */
    public String desc = "";
    /** Item-lore description (series 0 only). */
    @SerializedName("short")
    public String shortDesc = "";
    public List<StatRef> stats = new ArrayList<>();
    /** Levels obtainable from the Experimentation Table. */
    public List<Integer> experiments = new ArrayList<>();
    /** Non-null for enchants that level up by use (Champion, Compact, Cultivating...). */
    public LevelBy levelBy;

    public static final class StatRef {
        public String stat;
        public int series;
    }

    public static final class LevelBy {
        /** combat_xp, bow_combat_xp, blocks_mined, crops_harvested, logs_chopped, sea_creature_kills, s_runs */
        public String type;
        /** Counter needed for level II, III, ... (index 0 = level II). */
        public long[] thresholds = new long[0];
    }

    // ---- values -------------------------------------------------------------------------------

    public int series() { return values == null ? 0 : values.length; }

    /** Value of one series at one level (clamped into range); 0 when missing. */
    public double v(int series, int level) {
        if (values == null || series < 0 || series >= values.length || level <= 0) return 0;
        double[] s = values[series];
        if (s == null || s.length == 0) return 0;
        return s[Math.min(level, s.length) - 1];
    }

    public double v(int level) { return v(0, level); }

    public Rarity rarity(int level) {
        if (rarity == null || rarity.isEmpty()) return Rarity.COMMON;
        int i = Math.max(1, Math.min(level, rarity.size())) - 1;
        return Rarity.parse(rarity.get(i));
    }

    /** Table / anvil XP-level cost of one level. Falls back to the research's clone default (10 + 5 per level). */
    public int cost(int level) {
        if (cost != null && level >= 1 && level <= cost.length && cost[level - 1] > 0) return cost[level - 1];
        return 10 + 5 * (Math.max(1, level) - 1);   // TUNE: research 08 §3.2 "typical cost"
    }

    public boolean onTable() { return tableMax > 0; }

    public boolean levelsByUse() { return levelBy != null; }

    /** Counter needed to reach {@code level} (level 1 = 0). */
    public long thresholdFor(int level) {
        if (levelBy == null || level <= 1) return 0;
        long[] t = levelBy.thresholds;
        if (t == null || t.length == 0) return Long.MAX_VALUE;
        return t[Math.min(level - 2, t.length - 1)];
    }

    /** Level reached with this much progress (level-by-use enchants). */
    public int levelForCounter(long counter) {
        int lvl = 1;
        for (int l = 2; l <= maxLevel; l++) if (counter >= thresholdFor(l)) lvl = l; else break;
        return lvl;
    }

    // ---- applicability ------------------------------------------------------------------------

    public boolean appliesTo(ItemDef def) {
        if (def == null) return false;
        if (itemIds != null && itemIds.contains(def.id)) return true;
        if (def.category != null && categories != null && categories.contains(def.category.name())) return true;
        if (tags != null) for (String t : tags) if (def.has(t)) return true;
        return false;
    }

    public boolean conflictsWith(String other) {
        if (other == null || other.equals(id)) return false;
        return conflicts != null && conflicts.contains(other);
    }

    // ---- text ---------------------------------------------------------------------------------

    /** The full description at one level, numbers filled in. */
    public String describe(int level) {
        return fill(desc, level);
    }

    public String fill(String template, int level) {
        if (template == null) return "";
        String out = template;
        for (int s = 0; s < Math.max(1, series()); s++) out = out.replace("{" + s + "}", fmt(v(s, level)));
        return out;
    }

    /** Book / menu name: "&9Sharpness V" or "&d&lChimera V". */
    public String displayName(int level) {
        return (ultimate ? "&d&l" : "&9") + name + " " + roman(level);
    }

    /** Readable labels of where it applies ("Sword", "Fishing Rod"...). */
    public List<String> appliesToLabels() {
        List<String> out = new ArrayList<>();
        java.util.Set<String> seen = new HashSet<>();
        if (categories != null) for (String c : categories) {
            ItemCategory cat = ItemCategory.parse(c);
            String l = cat == ItemCategory.DUNGEON_WEAPON ? "Dungeon Weapon" : titleCase(c);
            if (seen.add(l)) out.add(l);
        }
        if (tags != null && tags.contains("farming_tool") && seen.add("Farming Tool")) out.add("Farming Tool");
        // item ids are reference-game ids (never shown to players): name the kind of thing instead
        if (itemIds != null && !itemIds.isEmpty() && seen.add("Special Weapon")) out.add("Special Weapon");
        return out;
    }

    /** The core EnchantDef this spec registers (data only; the effect lives in this module). */
    public EnchantDef toDef() {
        EnchantDef d = new LevelledEnchantDef(this);   // + describe(level): every number, for core's renderer
        d.id = id;
        d.name = name;
        d.maxLevel = maxLevel;
        d.tableMaxLevel = tableMax;
        d.ultimate = ultimate;
        if (categories != null) for (String c : categories) d.appliesTo.add(ItemCategory.parse(c));
        if (conflicts != null) d.conflicts.addAll(conflicts);
        d.description = shortDesc == null ? "" : shortDesc.replace("{0}", "%s");
        d.values = values != null && values.length > 0 && values[0] != null ? values[0].clone() : new double[0];
        int[] tc = new int[Math.max(0, tableMax)];
        for (int l = 1; l <= tableMax; l++) tc[l - 1] = cost(l);
        d.tableCost = tc;
        if (skill > 0) d.notes.add("Requires Enchanting " + skill);
        if (!combinable) d.notes.add("Cannot be combined");
        return d;
    }

    // ---- small helpers (pure; Text has Bukkit-free versions but keep this class standalone) ---

    public static String fmt(double v) {
        if (Math.abs(v - Math.rint(v)) < 1e-9) return String.format(Locale.ROOT, "%,d", (long) Math.rint(v));
        String s = String.format(Locale.ROOT, "%,.3f", v);
        while (s.endsWith("0")) s = s.substring(0, s.length() - 1);
        if (s.endsWith(".")) s = s.substring(0, s.length() - 1);
        return s;
    }

    private static final int[] RV = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    private static final String[] RS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    public static String roman(int n) {
        if (n <= 0) return String.valueOf(n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < RV.length; i++) while (n >= RV[i]) { n -= RV[i]; sb.append(RS[i]); }
        return sb.toString();
    }

    public static String titleCase(String id) {
        StringBuilder sb = new StringBuilder();
        for (String w : id.toLowerCase(Locale.ROOT).split("[_ ]+")) {
            if (w.isEmpty()) continue;
            if (sb.length() > 0) sb.append(' ');
            sb.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1));
        }
        return sb.toString();
    }
}
